# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SÜRTÜNMESİZ ORTAMDA MEKANİK ENERJİNİN KORUNUMU (FİZ.10.2.4)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TEMEL KORUNUM BAĞINTILARI</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Mekanik Enerji: Emek = Ek + Ep = Sabit</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• İlk Mekanik Enerji = Son Mekanik Enerji</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Ek,ilk + Ep,ilk = Ek,son + Ep,son</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• Azalan potansiyel enerji = Artan kinetik enerji</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">• -ΔEp = ΔEk  (Mekanik enerji değişimi ΔEmek = 0)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ÖZEL DÖNÜŞÜM UYGULAMALARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• h yüksekliğinden serbest düşen cisim:</text>\n  <text x="370" y="108" font-size="11.2" fill="#14532d">  m·g·h = (1/2)·m·v²  →  v = kök(2·g·h) (kütleden bağımsız)</text>\n  <text x="370" y="132" font-size="11.2" fill="#14532d">• Yatay düzlemde yay sıkıştırma:</text>\n  <text x="370" y="152" font-size="11.2" fill="#14532d">  (1/2)·m·v² = (1/2)·k·x²  (Kinetik → Esneklik potansiyel)</text>\n  <text x="370" y="178" font-size="11.2" fill="#14532d">• Sarkaç ve ray sistemlerinde uçlarda v = 0, Ep maksimum</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Sürtünmesiz ortamda h yüksekliğinden bırakılan cismin yere çarpma hızı kütlesine ve yolun eğimine bağlı değildir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SÜRTÜNMELİ ORTAMLARDA ENERJİ KAYBI VE ISIYA DÖNÜŞÜM</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">SÜRTÜNME KUVVETİNİN YAPTIĞI İŞ (Ws)</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• Sürtünmeli ortamda mekanik enerji KORUNMAZ (azalır)</text>\n  <text x="35" y="112" font-size="11.2" fill="#7f1d1d">• Toplam enerji (Mekanik + Isı) ise daima korunur</text>\n  <text x="35" y="136" font-size="11.2" fill="#7f1d1d">• Isıya dönüşen enerji: Eısı = |Ws| = fs · Δx</text>\n  <text x="35" y="160" font-size="11.2" fill="#7f1d1d">• Enerji denkliği: Emek,ilk = Emek,son + fs · Δx</text>\n  <text x="35" y="184" font-size="11.2" fill="#7f1d1d">• Yatay yolda v hızıyla fırlatılan cisim: (1/2)·m·v² = fs · x</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">FRENLEME MESAFESİ ANALİZİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Yatay düzlemde fs = k · m · g olduğundan:</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• (1/2) · m · v² = k · m · g · x  →  kütle (m) sadeleşir!</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Durma mesafesi: x = v² / (2 · k · g)</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Hız 2 katına çıkarsa (2v), durma mesafesi 4 katına (4x) çıkar</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Trafik güvenliğinde hız sınırının fiziksel dayanağıdır</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Sürtünmeli sistemde mekanik enerjideki azalma miktarı, sürtünme kuvvetinin yaptığı işe (ısıya) eşittir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">VERİM KAVRAMI VE ENERJİ TASARRUFU (FİZ.10.2.5)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">MATEMATİKSEL VERİM MODELİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Verim = Yapılan Faydalı İş / Harcanan Toplam Enerji</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• Verim = Alınan Güç (Pçıkış) / Verilen Güç (Pgiriş)</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• Yüzde Verim = (Efaydalı / Etoplam) × 100</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• Gerçek sistemlerde sürtünme nedeniyle Verim &lt; %100</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• Devridaim makinesi (%100 ve üzeri verim) imkânsızdır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">ENERJİ VERİMLİLİĞİ VE SÜRDÜRÜLEBİLİRLİK</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Enerji kimlik etiketleri: A sınıfı en yüksek verimli</text>\n  <text x="370" y="112" font-size="11.2" fill="#064e3b">• Akkor flamanlı lamba (%5 verim) yerine LED lamba (%85+)</text>\n  <text x="370" y="136" font-size="11.2" fill="#064e3b">• Sürtünmeyi azaltan yağlama ve bilyeli rulman sistemleri</text>\n  <text x="370" y="160" font-size="11.2" fill="#064e3b">• Binalarda ısı yalıtımı (mantolama ve çift cam)</text>\n  <text x="370" y="184" font-size="11.2" fill="#064e3b">• Karbon ayak izini küçültme ve millî serveti koruma</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Verim birimsiz bir orandır (0 ile 1 arasında); harcanan enerjinin ne kadarının amaca hizmet ettiğini gösterir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
